const N_G: f32 = 1.0;
const N_B: f32 = 1.02; // 1.0 + 0.02

struct Uniforms {
  u_resolution: vec2f,
  u_dpr: f32,
  // Host coordinate convention: 0 = WebGPU top-left, 1 = WebGL bottom-left.
  u_glOrigin: f32,
  u_mouse: vec2f,
  u_mouseSpring: vec2f,
  u_shapeWidth: f32,
  u_shapeHeight: f32,
  u_shapeRadius: f32,
  u_shapeRoundness: f32,
