.lg-stage {
  position: relative;
  isolation: isolate;
  overflow: hidden;
}
.lg-backdrop,
.lg-gpu,
.native-source {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}
.lg-backdrop,
.native-source {
  z-index: 0;
}
.native-source {
  pointer-events: auto;
}
.lg-gpu {
  z-index: 1;
}
.lg-surface {
  position: relative;
  z-index: 2;
  background: transparent;
  isolation: isolate;
}
.lg-content {
  position: relative;
  z-index: 1;
}
.lg-dom-material {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}
.lg-dom-material > svg {
  display: block;
  width: 100%;
  height: 100%;
}
