  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  z-index: 2;
  box-shadow:
    inset 0 1px 1px rgb(255 255 255 / calc(var(--lg-highlight, 0.36) * 0.9)),
    inset 1px 0 1px rgb(255 255 255 / calc(var(--lg-highlight, 0.36) * 0.25)),
    inset 0 -1px 1px rgb(255 255 255 / calc(var(--lg-highlight, 0.36) * 0.23));
