export type Backend = "auto" | "webgpu" | "webgl" | "svg" | "css" | "solid";
export type Capture = "scene" | "native-dom";
export type SurfaceKind = "card" | "control" | "panel";
export interface Controls {
  blur?: number;
  refraction?: number;
  highlight?: number;
