  return vec3f(
    dot(rgb, RGB_TO_XYZ_M_COL0),
    dot(rgb, RGB_TO_XYZ_M_COL1),
    dot(rgb, RGB_TO_XYZ_M_COL2)
  );
}

fn XYZ_TO_RGB(xyz: vec3f) -> vec3f {
  return vec3f(
    dot(xyz, XYZ_TO_RGB_M_COL0),
    dot(xyz, XYZ_TO_RGB_M_COL1),
    dot(xyz, XYZ_TO_RGB_M_COL2)
  );
}

