  return RGB_TO_XYZ(SRGB_TO_RGB(srgb));
}

fn XYZ_TO_SRGB(xyz: vec3f) -> vec3f {
  return RGB_TO_SRGB(XYZ_TO_RGB(xyz));
}

fn XYZ_TO_LAB_F(x: f32) -> f32 {
  if (x > 0.00885645167) {
    return pow(x, 0.333333333);
  }
  return 7.78703703704 * x + 0.13793103448;
}

