  // vec3 normalColor = vec3((normal * 0.5 + 0.5) * edgeEffect, 0.0);
  // vec3 normalColor = vec3(clamp(normal.x, 0.0, 1.0), abs(normal.y), clamp(-normal.x, 0.0, 1.0));
